// Each authored row stores the correct option first; deterministic rotation avoids answer-position bias.
const bank = (prefix, rows, studyFor, objectiveFor = topic => topic, answerOffset = 0) => rows.map(([topic, prompt, correct, wrong1, wrong2, wrong3, explanation], index) => {
    const answer = (index + answerOffset) % 4;
    const options = [correct, wrong1, wrong2, wrong3];
    return {
        id: `${prefix}-${String(index + 1).padStart(2, "0")}`, prompt,
        options: options.map((_, option) => options[(option - answer + 4) % 4]),
        answer, explanation, objective: objectiveFor(topic), study: studyFor(topic), topic
    };
});

