const modules = moduleDefinitions.map(([id, title, summary, goals, lessons, brief, hints], moduleIndex) => ({
    id, title, summary, goals, lessons, challenge: { brief, hints },
    assessment: {
        count: 5,
        blueprint: lessons.map((item, index) => ({ topic: item.id, count: index < 2 ? 2 : 1 })),
        bank: bank(`applied-${id}-check`, moduleRows[id].map(([number, ...row]) => [`applied-${id}-${number}`, ...row]),
            topic => `#${topic}`, topic => {
                const item = lessons.find(entry => entry.id === topic);
                return `Apply ${item.title.toLowerCase()} to the branch scenario.`;
            }, (moduleIndex % 2) * 2)
    }
}));

